"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[44299],{65631(e,a,r){r.r(a),r.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>i,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"cursos/cleancode/modulos/limites-integracion/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 es el \\"Strangler Fig Pattern\\" de Martin Fowler y c\xf3mo se aplica a la modernizaci\xf3n gradual de un sistema legacy? \xbfQu\xe9 relaci\xf3n tiene con los l\xedmites y adapters?","source":"@site/docs/cursos/cleancode/modulos/07-limites-integracion/cuestionario.md","sourceDirName":"cursos/cleancode/modulos/07-limites-integracion","slug":"/cursos/cleancode/modulos/limites-integracion/cuestionario","permalink":"/sasf-temarios/cursos/cleancode/modulos/limites-integracion/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/cleancode/modulos/limites-integracion/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/cleancode/modulos/limites-integracion/ejercicio"}}');var s=r(74848),o=r(28453);const i={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},t=void 0,c={},l=[{value:"2. [Investigar] \xbfQu\xe9 es el &quot;Strangler Fig Pattern&quot; de Martin Fowler y c\xf3mo se aplica a la modernizaci\xf3n gradual de un sistema legacy? \xbfQu\xe9 relaci\xf3n tiene con los l\xedmites y adapters?",id:"2-investigar-qu\xe9-es-el-strangler-fig-pattern-de-martin-fowler-y-c\xf3mo-se-aplica-a-la-modernizaci\xf3n-gradual-de-un-sistema-legacy-qu\xe9-relaci\xf3n-tiene-con-los-l\xedmites-y-adapters",level:3},{value:"3. [Investigar] \xbfQu\xe9 son los &quot;Consumer-Driven Contracts&quot; (CDC) y c\xf3mo herramientas como Pact o Spring Cloud Contract implementan este concepto? \xbfPor qu\xe9 es una evoluci\xf3n del enfoque de Learning Tests que la clase propone?",id:"3-investigar-qu\xe9-son-los-consumer-driven-contracts-cdc-y-c\xf3mo-herramientas-como-pact-o-spring-cloud-contract-implementan-este-concepto-por-qu\xe9-es-una-evoluci\xf3n-del-enfoque-de-learning-tests-que-la-clase-propone",level:3},{value:"4. [Investigar] \xbfQu\xe9 clasificaci\xf3n de &quot;Test Doubles&quot; estableci\xf3 Gerard Meszaros en &quot;xUnit Test Patterns&quot;? \xbfQu\xe9 tipos de doubles son m\xe1s apropiados para testear l\xedmites y adapters, y por qu\xe9?",id:"4-investigar-qu\xe9-clasificaci\xf3n-de-test-doubles-estableci\xf3-gerard-meszaros-en-xunit-test-patterns-qu\xe9-tipos-de-doubles-son-m\xe1s-apropiados-para-testear-l\xedmites-y-adapters-y-por-qu\xe9",level:3},{value:"5. [Conectar] La clase describe &quot;Learning Tests&quot; para explorar APIs de terceros. \xbfC\xf3mo se relaciona este concepto con los &quot;Characterization Tests&quot; de Michael Feathers y qu\xe9 diferencia fundamental hay entre ambos? \xbfCu\xe1ndo usar\xedas uno y cu\xe1ndo el otro?",id:"5-conectar-la-clase-describe-learning-tests-para-explorar-apis-de-terceros-c\xf3mo-se-relaciona-este-concepto-con-los-characterization-tests-de-michael-feathers-y-qu\xe9-diferencia-fundamental-hay-entre-ambos-cu\xe1ndo-usar\xedas-uno-y-cu\xe1ndo-el-otro",level:3},{value:"6. [Conectar] La clase recomienda encapsular c\xf3digo de terceros detr\xe1s de interfaces (adapter). \xbfC\xf3mo extiende el &quot;Dependency Inversion Principle&quot; (la D de SOLID) este concepto? \xbfQu\xe9 dice Robert C. Martin sobre la diferencia entre &quot;depender de interfaces&quot; y &quot;depender de abstracciones&quot;?",id:"6-conectar-la-clase-recomienda-encapsular-c\xf3digo-de-terceros-detr\xe1s-de-interfaces-adapter-c\xf3mo-extiende-el-dependency-inversion-principle-la-d-de-solid-este-concepto-qu\xe9-dice-robert-c-martin-sobre-la-diferencia-entre-depender-de-interfaces-y-depender-de-abstracciones",level:3},{value:"7. [Conectar] La clase explica que los Learning Tests &quot;alertan cuando una librer\xeda cambia&quot;. \xbfC\xf3mo se relaciona esto con el versionado sem\xe1ntico (SemVer) y qu\xe9 limitaciones tiene confiar SOLO en Learning Tests sin verificar el semantic versioning de dependencias?",id:"7-conectar-la-clase-explica-que-los-learning-tests-alertan-cuando-una-librer\xeda-cambia-c\xf3mo-se-relaciona-esto-con-el-versionado-sem\xe1ntico-semver-y-qu\xe9-limitaciones-tiene-confiar-solo-en-learning-tests-sin-verificar-el-semantic-versioning-de-dependencias",level:3},{value:"8. [Cuestionar] La clase presenta los adapters como la soluci\xf3n para desacoplar c\xf3digo de terceros. \xbfQu\xe9 sostiene Yegor Bugayenko sobre el uso excesivo de interfaces y adapters? \xbfCu\xe1l es su cr\xedtica a lo que \xe9l llama &quot;interface-itis&quot; y c\xf3mo se relaciona con el principio YAGNI?",id:"8-cuestionar-la-clase-presenta-los-adapters-como-la-soluci\xf3n-para-desacoplar-c\xf3digo-de-terceros-qu\xe9-sostiene-yegor-bugayenko-sobre-el-uso-excesivo-de-interfaces-y-adapters-cu\xe1l-es-su-cr\xedtica-a-lo-que-\xe9l-llama-interface-itis-y-c\xf3mo-se-relaciona-con-el-principio-yagni",level:3},{value:"9. [Cuestionar] La clase recomienda aislar el c\xf3digo de terceros en adapters. \xbfQu\xe9 sucede con librer\xedas que se vuelven &quot;est\xe1ndar de la industria&quot; y se integran profundamente en todo el c\xf3digo (ej. Jackson para JSON en Java, React para UI)? \xbfEs pr\xe1ctico envolver Jackson en un adapter? \xbfD\xf3nde traz\xe1s la l\xednea entre &quot;dependencia aceptable&quot; y &quot;dependencia que requiere adapter&quot;?",id:"9-cuestionar-la-clase-recomienda-aislar-el-c\xf3digo-de-terceros-en-adapters-qu\xe9-sucede-con-librer\xedas-que-se-vuelven-est\xe1ndar-de-la-industria-y-se-integran-profundamente-en-todo-el-c\xf3digo-ej-jackson-para-json-en-java-react-para-ui-es-pr\xe1ctico-envolver-jackson-en-un-adapter-d\xf3nde-traz\xe1s-la-l\xednea-entre-dependencia-aceptable-y-dependencia-que-requiere-adapter",level:3},{value:"10. [Cuestionar] La clase propone caracterizar c\xf3digo legacy con tests. En la pr\xe1ctica, caracterizar una clase de 2000 l\xedneas sin tests previos puede tomar d\xedas. \xbfQu\xe9 t\xe9cnica de &quot;seam&quot; propone Michael Feathers para testear c\xf3digo legacy sin caracterizarlo completamente? \xbfQu\xe9 es un &quot;sensing variable&quot; y c\xf3mo se usa para refactoring seguro sin cobertura total?",id:"10-cuestionar-la-clase-propone-caracterizar-c\xf3digo-legacy-con-tests-en-la-pr\xe1ctica-caracterizar-una-clase-de-2000-l\xedneas-sin-tests-previos-puede-tomar-d\xedas-qu\xe9-t\xe9cnica-de-seam-propone-michael-feathers-para-testear-c\xf3digo-legacy-sin-caracterizarlo-completamente-qu\xe9-es-un-sensing-variable-y-c\xf3mo-se-usa-para-refactoring-seguro-sin-cobertura-total",level:3}];function d(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-el-strangler-fig-pattern-de-martin-fowler-y-c\xf3mo-se-aplica-a-la-modernizaci\xf3n-gradual-de-un-sistema-legacy-qu\xe9-relaci\xf3n-tiene-con-los-l\xedmites-y-adapters",children:'2. [Investigar] \xbfQu\xe9 es el "Strangler Fig Pattern" de Martin Fowler y c\xf3mo se aplica a la modernizaci\xf3n gradual de un sistema legacy? \xbfQu\xe9 relaci\xf3n tiene con los l\xedmites y adapters?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Martin Fowler describi\xf3 el Strangler Fig Pattern en 2004 (martinfowler.com, inspirado en la higuera estranguladora que crece alrededor de un \xe1rbol hu\xe9sped hasta reemplazarlo). La estrategia: en lugar de reescribir un sistema legacy de golpe (big-bang rewrite, extremadamente riesgoso), constru\xeds un NUEVO sistema alrededor del legacy, y gradualmente redirig\xeds funcionalidad del viejo al nuevo mediante un "routing layer" que intercepta las requests y decide qu\xe9 sistema las maneja. Los adapters son la herramienta CLAVE: el nuevo sistema expone los MISMOS puertos/interfaces que el viejo, por lo que el routing layer es transparente para los clientes. El sistema legacy eventualmente queda reducido a cero funcionalidad y se retira. Relaci\xf3n con el m\xf3dulo: los adapters no solo sirven para aislar librer\xedas de terceros \u2014son la herramienta fundamental para modernizar sistemas legacy de manera incremental. El proyecto final del curso (refactorizar un sistema legacy de biblioteca) es EXACTAMENTE un escenario donde el Strangler Fig se aplicar\xeda si el sistema estuviera en producci\xf3n.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase enfoca los l\xedmites como integraci\xf3n con c\xf3digo externo (librer\xedas). Fowler extiende el concepto al l\xedmite m\xe1s peligroso: tu propio c\xf3digo legacy. El Strangler Fig es el patr\xf3n m\xe1s importante que el alumno debe conocer para trabajar con sistemas legacy en producci\xf3n."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"3-investigar-qu\xe9-son-los-consumer-driven-contracts-cdc-y-c\xf3mo-herramientas-como-pact-o-spring-cloud-contract-implementan-este-concepto-por-qu\xe9-es-una-evoluci\xf3n-del-enfoque-de-learning-tests-que-la-clase-propone",children:'3. [Investigar] \xbfQu\xe9 son los "Consumer-Driven Contracts" (CDC) y c\xf3mo herramientas como Pact o Spring Cloud Contract implementan este concepto? \xbfPor qu\xe9 es una evoluci\xf3n del enfoque de Learning Tests que la clase propone?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Consumer-Driven Contracts (Ian Robinson, 2006, ThoughtWorks) invierte el modelo tradicional de API: en lugar de que el PROVEEDOR defina el contrato y los CONSUMIDORES se adapten, cada consumidor publica sus EXPECTATIVAS del provider como un contrato (ej. "cuando llamo a GET /users/5, espero JSON con campos id, name, email"). El provider recopila todos los contratos de todos sus consumidores y verifica que su implementaci\xf3n los SATISFACE. Herramientas: Pact (consumer escribe tests que generan contratos; provider verifica contra esos contratos en CI); Spring Cloud Contract (provider define contratos con stubs generados autom\xe1ticamente para consumers). Relaci\xf3n con Learning Tests: ambos verifican que una dependencia externa se comporta como esperamos. La diferencia: (a) Learning Tests son UNILATERALES (vos teste\xe1s que entendiste la API), (b) CDC es BILATERAL (el provider se compromete a no romper los contratos de sus consumers), (c) CDC escala a m\xfaltiples equipos y servicios, Learning Tests son para una librer\xeda que no se comunica con vos.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase propone Learning Tests para librer\xedas. CDC extiende la filosof\xeda de verificar expectativas a integraciones entre servicios, que es el caso m\xe1s com\xfan en arquitecturas de microservicios que el alumno encontrar\xe1 profesionalmente."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"4-investigar-qu\xe9-clasificaci\xf3n-de-test-doubles-estableci\xf3-gerard-meszaros-en-xunit-test-patterns-qu\xe9-tipos-de-doubles-son-m\xe1s-apropiados-para-testear-l\xedmites-y-adapters-y-por-qu\xe9",children:'4. [Investigar] \xbfQu\xe9 clasificaci\xf3n de "Test Doubles" estableci\xf3 Gerard Meszaros en "xUnit Test Patterns"? \xbfQu\xe9 tipos de doubles son m\xe1s apropiados para testear l\xedmites y adapters, y por qu\xe9?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Gerard Meszaros, en "xUnit Test Patterns: Refactoring Test Code" (2007), clasific\xf3 los test doubles en 5 tipos: (1) Dummy: objeto que se pasa pero nunca se usa, solo para satisfacer par\xe1metros. (2) Stub: retorna respuestas predefinidas siempre igual. (3) Spy: registra las llamadas que recibe para verificarlas despu\xe9s. (4) Mock: objeto preprogramado con expectativas de c\xf3mo DEBE ser llamado (verifica comportamiento). (5) Fake: implementaci\xf3n ligera pero funcional (ej. base de datos en memoria, no mock de DB). Para testear adapters: (a) Fake del servicio externo es IDEAL \u2014simula comportamiento real (happy path, timeouts, errores), (b) Mock solo cuando el comportamiento exacto del adapter hacia el exterior es la expectativa, (c) Stub para depender del dato que el adapter retorna sin importar c\xf3mo. La clase menciona "mocks" informalmente pero sin la taxonom\xeda de Meszaros, lo cual lleva a usar mock para todo y producir tests fr\xe1giles acoplados a implementaci\xf3n.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": Meszaros es LA referencia en patrones de testing. Sin su taxonom\xeda, los desarrolladores tienden a abusar de mocks (testeando implementaci\xf3n en lugar de comportamiento) o no saber cu\xe1ndo un Fake es mejor. Esto es esencial para el m\xf3dulo porque los adapters EXISTEN para ser testeados con doubles apropiados."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"5-conectar-la-clase-describe-learning-tests-para-explorar-apis-de-terceros-c\xf3mo-se-relaciona-este-concepto-con-los-characterization-tests-de-michael-feathers-y-qu\xe9-diferencia-fundamental-hay-entre-ambos-cu\xe1ndo-usar\xedas-uno-y-cu\xe1ndo-el-otro",children:'5. [Conectar] La clase describe "Learning Tests" para explorar APIs de terceros. \xbfC\xf3mo se relaciona este concepto con los "Characterization Tests" de Michael Feathers y qu\xe9 diferencia fundamental hay entre ambos? \xbfCu\xe1ndo usar\xedas uno y cu\xe1ndo el otro?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Ambos son tests que no prueban correcci\xf3n sino que DOCUMENTAN comportamiento existente. La diferencia fundamental es el OBJETO de estudio: (a) Learning Tests: exploran una API EXTERNA NUEVA que vas a integrar \u2014el comportamiento documentado deber\xeda ser ESTABLE (la librer\xeda publica su API). (b) Characterization Tests (Feathers, "Working Effectively with Legacy Code", 2004): documentan el comportamiento de tu PROPIO C\xd3DIGO LEGACY que NO entend\xe9s completamente y que NO TIENE TESTS \u2014el comportamiento documentado puede ser INCORRECTO (bugs), pero lo document\xe1s ANTES de refactorizar para detectar regresiones. Feathers es expl\xedcito: estos tests no validan que el c\xf3digo sea correcto, solo que "as\xed funcionaba antes de que yo lo tocara". Cu\xe1ndo usar: Learning Tests cuando integr\xe1s algo nuevo de afuera. Characterization Tests cuando vas a modificar c\xf3digo legacy propio sin tests. Ambos comparten la filosof\xeda: "primero entiendo qu\xe9 hace, luego cambio".']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase presenta Learning Tests para APIs externas. El proyecto del curso involucra refactorizar un sistema legacy (de biblioteca), donde los Characterization Tests son la herramienta PRINCIPAL. Sin ellos, refactorizar c\xf3digo legacy es cirug\xeda sin anestesia. Feathers es el complemento indispensable al cap\xedtulo de L\xedmites cuando el "tercero" es tu yo del pasado.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"6-conectar-la-clase-recomienda-encapsular-c\xf3digo-de-terceros-detr\xe1s-de-interfaces-adapter-c\xf3mo-extiende-el-dependency-inversion-principle-la-d-de-solid-este-concepto-qu\xe9-dice-robert-c-martin-sobre-la-diferencia-entre-depender-de-interfaces-y-depender-de-abstracciones",children:'6. [Conectar] La clase recomienda encapsular c\xf3digo de terceros detr\xe1s de interfaces (adapter). \xbfC\xf3mo extiende el "Dependency Inversion Principle" (la D de SOLID) este concepto? \xbfQu\xe9 dice Robert C. Martin sobre la diferencia entre "depender de interfaces" y "depender de abstracciones"?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": El Dependency Inversion Principle (Martin, 1996, art\xedculo en C++ Report) establece: (a) m\xf3dulos de alto nivel no deben depender de m\xf3dulos de bajo nivel; ambos deben depender de abstracciones. (b) Las abstracciones no deben depender de detalles; los detalles deben depender de abstracciones. La clase muestra c\xf3mo encapsular c\xf3digo de terceros (detalle) detr\xe1s de una interfaz (abstracci\xf3n), pero Martin va m\xe1s all\xe1: la interfaz debe ser PROPIEDAD del m\xf3dulo de alto nivel (tu dominio), no del m\xf3dulo de bajo nivel. Esto es sutil pero crucial: ",(0,s.jsx)(a.code,{children:"PaymentGateway"})," (interfaz) vive en el paquete de dominio ",(0,s.jsx)(a.code,{children:"com.empresa.pagos"}),", NO en ",(0,s.jsx)(a.code,{children:"com.terceros.fastpay"}),". La clase no enfatiza la PROPIEDAD de la interfaz, que es la verdadera inversi\xf3n de dependencia. Si la interfaz ",(0,s.jsx)(a.code,{children:"PaymentGateway"})," est\xe1 en el paquete del adapter, no hay inversi\xf3n real \u2014el dominio sigue dependiendo de un paquete que depende del tercero. La regla completa: (1) cre\xe1 la interfaz en tu dominio, (2) el adapter IMPLEMENTA tu interfaz, (3) el adapter depende del tercero, (4) tu dominio NO depende de nada externo."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase presenta el adapter como encapsulamiento sin enfatizar que la DIRECCI\xd3N de la dependencia es la clave. Sin esta precisi\xf3n, los alumnos crean adapters donde la interfaz est\xe1 junto al adapter (mismo paquete) y el dominio depende de ese paquete \u2014sin inversi\xf3n real. DIP es el principio arquitect\xf3nico m\xe1s malinterpretado y su aplicaci\xf3n correcta es lo que distingue dise\xf1o limpio de adapters cosm\xe9ticos."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"7-conectar-la-clase-explica-que-los-learning-tests-alertan-cuando-una-librer\xeda-cambia-c\xf3mo-se-relaciona-esto-con-el-versionado-sem\xe1ntico-semver-y-qu\xe9-limitaciones-tiene-confiar-solo-en-learning-tests-sin-verificar-el-semantic-versioning-de-dependencias",children:'7. [Conectar] La clase explica que los Learning Tests "alertan cuando una librer\xeda cambia". \xbfC\xf3mo se relaciona esto con el versionado sem\xe1ntico (SemVer) y qu\xe9 limitaciones tiene confiar SOLO en Learning Tests sin verificar el semantic versioning de dependencias?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Semantic Versioning (Tom Preston-Werner, semver.org, 2011) establece MAJOR.MINOR.PATCH: MAJOR para breaking changes, MINOR para features nuevas compatibles, PATCH para bug fixes. La conexi\xf3n con Learning Tests: si una librer\xeda cambia MINOR o PATCH, tus Learning Tests NO deber\xedan fallar (si fallan, el autor de la librer\xeda viol\xf3 SemVer). Si cambia MAJOR, tus tests DEBER\xcdAN fallar en alg\xfan punto. Las limitaciones de depender solo de Learning Tests: (a) si ten\xe9s 100 dependencias, ejecutar Learning Tests para TODAS en cada upgrade es costoso \u2014el versionado sem\xe1ntico te permite priorizar: upgrades PATCH no deber\xedan romper nada y pod\xe9s automatizarlos (Renovate, Dependabot), (b) Learning Tests no cubren TODOS los comportamientos de una librer\xeda \u2014solo los que vos us\xe1s. Un breaking change en una API que no us\xe1s pasar\xe1 desapercibido en tus tests pero puede ser se\xf1al de que la librer\xeda es inestable, (c) herramientas como ",(0,s.jsx)(a.code,{children:"dependabot"})," + CI que ejecutan tu suite completa de tests en upgrades autom\xe1ticos combinan SemVer + verificaci\xf3n de comportamiento. La clase presenta Learning Tests como soluci\xf3n aislada; en la pr\xe1ctica, es una capa de una estrategia multi-capas de gesti\xf3n de dependencias."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase no menciona versionado de dependencias. En el desarrollo real, gestionar versiones es tan importante como aislar dependencias. El alumno debe entender que los Learning Tests son parte de un ecosistema de pr\xe1cticas (SemVer, lockfiles, automated dependency updates, reproducible builds)."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"8-cuestionar-la-clase-presenta-los-adapters-como-la-soluci\xf3n-para-desacoplar-c\xf3digo-de-terceros-qu\xe9-sostiene-yegor-bugayenko-sobre-el-uso-excesivo-de-interfaces-y-adapters-cu\xe1l-es-su-cr\xedtica-a-lo-que-\xe9l-llama-interface-itis-y-c\xf3mo-se-relaciona-con-el-principio-yagni",children:'8. [Cuestionar] La clase presenta los adapters como la soluci\xf3n para desacoplar c\xf3digo de terceros. \xbfQu\xe9 sostiene Yegor Bugayenko sobre el uso excesivo de interfaces y adapters? \xbfCu\xe1l es su cr\xedtica a lo que \xe9l llama "interface-itis" y c\xf3mo se relaciona con el principio YAGNI?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Yegor Bugayenko, en "Elegant Objects" (2017, Volumen 2), critica lo que llama "interface-itis": la pr\xe1ctica de crear interfaces para todo "por si acaso cambia la implementaci\xf3n". Su argumento: (a) las interfaces no son gratis \u2014cada interfaz es una capa de indirecci\xf3n que hace el c\xf3digo m\xe1s dif\xedcil de navegar, (b) "interfaz + \xfanica implementaci\xf3n" viola YAGNI: si solo ten\xe9s un ',(0,s.jsx)(a.code,{children:"PayPalAdapter"}),", \xbfpara qu\xe9 existe ",(0,s.jsx)(a.code,{children:"PaymentGateway"}),'? La respuesta "para testear" no alcanza \u2014pod\xe9s mockear la clase concreta o usar un Fake, (c) la proliferaci\xf3n de interfaces oscurece el "entry point" real: cuando ten\xe9s 50 interfaces y 50 implementaciones, encontrar QU\xc9 implementaci\xf3n se usa en producci\xf3n requiere navegar la configuraci\xf3n de inyecci\xf3n de dependencias. Bugayenko aboga por: crear interfaz SOLO cuando hay al menos DOS implementaciones en producci\xf3n (no en tests). La interface prematura es una abstracci\xf3n especulativa. La clase recomienda adapters como principio; Bugayenko recuerda que cada adapter es costo de complejidad.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase asume que los adapters son siempre buenos. Bugayenko es una voz cr\xedtica que obliga a justificar cada adapter. El alumno debe poder argumentar CU\xc1NDO un adapter se justifica y cu\xe1ndo es sobre-ingenier\xeda, en lugar de aplicar el patr\xf3n por inercia."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"9-cuestionar-la-clase-recomienda-aislar-el-c\xf3digo-de-terceros-en-adapters-qu\xe9-sucede-con-librer\xedas-que-se-vuelven-est\xe1ndar-de-la-industria-y-se-integran-profundamente-en-todo-el-c\xf3digo-ej-jackson-para-json-en-java-react-para-ui-es-pr\xe1ctico-envolver-jackson-en-un-adapter-d\xf3nde-traz\xe1s-la-l\xednea-entre-dependencia-aceptable-y-dependencia-que-requiere-adapter",children:'9. [Cuestionar] La clase recomienda aislar el c\xf3digo de terceros en adapters. \xbfQu\xe9 sucede con librer\xedas que se vuelven "est\xe1ndar de la industria" y se integran profundamente en todo el c\xf3digo (ej. Jackson para JSON en Java, React para UI)? \xbfEs pr\xe1ctico envolver Jackson en un adapter? \xbfD\xf3nde traz\xe1s la l\xednea entre "dependencia aceptable" y "dependencia que requiere adapter"?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': La l\xednea se traza con el criterio de "riesgo de cambio" y "profundidad de integraci\xf3n". (a) Jackson es ubicuo en Java: est\xe1 en Spring Boot, en cada serializaci\xf3n, y wrappearlo ser\xeda un adapter colosal que duplicar\xeda todo su API. Riesgo de cambio: BAJO (es el est\xe1ndar de facto, mantenido por FasterXML, cambios breaking son raros). Conclusi\xf3n: no necesita adapter. (b) React en frontend es ubicuo y profundo: no tiene sentido wrappearlo. (c) Una pasarela de pago espec\xedfica (MercadoPago, Stripe) tiene riesgo de cambio ALTO (cambian APIs, cambian precios, pueden ser reemplazadas por un competidor), profundidad de integraci\xf3n BAJA (llam\xe1s 3-4 endpoints). Conclusi\xf3n: necesita adapter. (d) Una librer\xeda de logging: profundidad ALTA (est\xe1 en todas partes), riesgo de cambio BAJO. Conclusi\xf3n: usar SLF4J como fachada (que ya es un adapter est\xe1ndar), no crear tu propio wrapper. La regla pr\xe1ctica: cre\xe1 adapter cuando la dependencia es REEMPLAZABLE y su API no es ubicua. No cre\xe9s adapter para el framework o las librer\xedas que definen el paradigma de tu stack.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase da una regla (siempre encapsular) sin criterio de costo/beneficio. El resultado es que alumnos crean wrappers para todo, incluyendo ",(0,s.jsx)(a.code,{children:"List"})," o ",(0,s.jsx)(a.code,{children:"Optional"}),', y terminan con sistemas llenos de indirecci\xf3n. El equipo de Google tiene gu\xedas sobre "acceptable dependencies": librer\xedas que todo el c\xf3digo puede usar directamente (Guava, protobuf) vs. librer\xedas que requieren wrapper. El alumno debe desarrollar criterio pragm\xe1tico.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"10-cuestionar-la-clase-propone-caracterizar-c\xf3digo-legacy-con-tests-en-la-pr\xe1ctica-caracterizar-una-clase-de-2000-l\xedneas-sin-tests-previos-puede-tomar-d\xedas-qu\xe9-t\xe9cnica-de-seam-propone-michael-feathers-para-testear-c\xf3digo-legacy-sin-caracterizarlo-completamente-qu\xe9-es-un-sensing-variable-y-c\xf3mo-se-usa-para-refactoring-seguro-sin-cobertura-total",children:'10. [Cuestionar] La clase propone caracterizar c\xf3digo legacy con tests. En la pr\xe1ctica, caracterizar una clase de 2000 l\xedneas sin tests previos puede tomar d\xedas. \xbfQu\xe9 t\xe9cnica de "seam" propone Michael Feathers para testear c\xf3digo legacy sin caracterizarlo completamente? \xbfQu\xe9 es un "sensing variable" y c\xf3mo se usa para refactoring seguro sin cobertura total?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Michael Feathers define "seam" como un punto en el c\xf3digo donde pod\xe9s cambiar el comportamiento sin editar directamente ese punto. T\xe9cnicas espec\xedficas para testear sin caracterizar TODO: (a) "Extract and Override Call": en lugar de testear la clase entera, en la subclase de test sobreescrib\xeds la dependencia problem\xe1tica (ej. ',(0,s.jsx)(a.code,{children:"getConnection()"}),' que requiere BD real) para retornar un fake. No teste\xe1s la clase original \u2014reemplaz\xe1s UNA dependencia para aislar el comportamiento que quer\xe9s modificar. (b) "Sensing Variable": una variable temporal que agreg\xe1s al c\xf3digo para "espiar" el estado interno en tests. Feathers sugiere que durante la refactorizaci\xf3n, agregar variables de sensing que capturen efectos intermedios y luego removerlas cuando el c\xf3digo est\xe9 limpio y testeable. La filosof\xeda: no necesit\xe1s 80% de cobertura ANTES de refactorizar; necesit\xe1s seams estrat\xe9gicos que te permitan cambiar partes con confianza. La clase asume que caracterizar\xe1s todo el legacy previamente; Feathers \u2014que lidi\xf3 con c\xf3digo mucho peor\u2014 propone t\xe9cnicas para cambiar c\xf3digo mientras lo teste\xe1s incrementalmente.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": El proyecto final pide >80% de cobertura y la clase sugiere characterization tests. En c\xf3digo legacy real, llegar a 80% de cobertura antes de refactorizar es inviable. Feathers es el complemento pragm\xe1tico que ense\xf1a a refactorizar con red de seguridad PARCIAL, que es la realidad de todo proyecto legacy. El alumno debe conocer estas t\xe9cnicas para no paralizarse ante la magnitud del c\xf3digo a testear."]})]})}function u(e={}){const{wrapper:a}={...(0,o.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,a,r){r.d(a,{R:()=>i,x:()=>t});var n=r(96540);const s={},o=n.createContext(s);function i(e){const a=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(o.Provider,{value:a},e.children)}}}]);